head.script:
scwin.trigger3_onclick = function(e) {
    for (var i = 0; i < grid1.getRowCount(); i++) {
        if (i != 0 && i != 4 && i != 6 && i != 8 && i != 10 && i != 11 && i != 12 && i != 13) {
            grid1.setRowVisible(i, false);
        }
    }
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById('grid1_cell_9_0').textContent == "row_13";
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1').setBottomRowIndex(20)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1').setBottomRowIndex(7)");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    window.arr = [];
    for (var i = 0; i < 21; i++) {
        arr.push("row_" + i);
        arr.push("data1");
        arr.push("data2");
    }
    grid1.setData(arr);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 23-Feb-2018
    //End unitTest
}
